package main

import (
	"fmt"
	"strconv"
)

func perm(n, k int) int64 {
	if k > n {
		return 0
	}
	v := int64(1)
	for t := 0; t < k; t++ {
		v *= int64(n - t)
	}
	return v
}

// upto counts integers in [0, x] whose decimal digits are pairwise distinct.
func upto(x int64) int64 {
	if x < 0 {
		return 0
	}
	ds := strconv.FormatInt(x, 10)
	L := len(ds)
	ans := int64(1) // the number 0
	for length := 1; length < min(L, 11); length++ {
		ans += 9 * perm(9, length-1)
	}
	var used [10]bool
	usedCount := 0
	for i := 0; i < L; i++ {
		d, low, remaining := int(ds[i]-'0'), 0, L-i-1
		if i == 0 {
			low = 1
		}
		for c := low; c < d; c++ {
			if !used[c] {
				ans += perm(9-usedCount, remaining)
			}
		}
		if used[d] || (i == 0 && d == 0) {
			return ans
		}
		used[d] = true
		usedCount++
	}
	return ans + 1 // x itself has distinct digits
}

func main() {
	var a, b int64
	fmt.Scan(&a, &b)
	fmt.Println(upto(b) - upto(a-1))
}
